local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[404601]=b({e[46057],404601,false,117,246,false,200046,false,"deco/character/jichuanxiang",false,60,1,false,false,false,120,"0.959999978542328",false,false,false,false,false,false,false,"90,-200,1.04","210,40,0.96","20,20,0.96","210,40,0.96","20,20,0.96","0,0,0.96","180,50,0.96","140,50,0.96","180,50,0.96","140,50,0.96",false,1686,917,400,1151,619,1699,2378,1151,619,1699,1258,"jichuanxiang"},h)g[404602]=b({e[17034],404602,1,4,247,"「まったく、何っ回も負けてんのにま～た勝負を挑んで来るなんてな。今日は何で勝負する？ 『無敗の伝説』は伊達じゃないってわからせてやるよ！」",200046,1,"deco/character/jichuanxiang_0",false,60,false,false,false,false,false,"0",1842,873,400,1151,619,1520,2260,1151,619,1520,1214},h)g[404603]=b({e[17034],404603,5,67,248,"「響く鈴ども～！　準備はできてるかい？　そろそろ響様の【地上最強】新年配信が始まるぞー！　それじゃ一緒にカウントダウンをよろしく！　３――！　２――！　１―――！　ハッピーニューイヤー！！」",200046,2,"deco/character/jichuanxiang_XN",0,false,1,1,false,false,false,"0",1845,890,398,1052,453,1843,2526,1052,588,1843,false,1,5270,5000,2468,6652,6666,3666,4000,3166,10000,false,6666},h)g[404604]=b({e[21034],404604,15,118,249,"「ふふーん、世界一のボーカル様の初ライブへようこそ！　……コラ、最前列三番目のお前！　今話聞いてなかっただろ！　この後、響様のグッズ十個お買い上げな！　わかったか？」",200046,2,"deco/character/jichuanxiang_OX",0,false,1,false,false,false,false,false,false,false,false,"240,-40,0.94",1890,885,398,831,415,2406,2837,831,583,2406},h)g[404701]=b({e[16023],404701,false,119,250,false,200047,false,"deco/character/laien",false,60,false,false,false,false,-275,"110,20,1","50,-40,1","100,-40,1",false,false,false,"0,-20,1","80,-20,1",false,false,false,1792,884,366,1110,450,1698,2940,1110,566,1698},h)g[404702]=b({e[17034],404702,1,4,251,"「いいえ、まだ眠くありません。ただ、目が痒いだけです。\n本当です、もうちょっと遊べますよ。\nだから、僕を置いていかないでくださいね？ お姉さま……。」",200047,1,"deco/character/laien_0",false,60,false,false,false,false,false,"0",1775,869,399,939,728,2045,2093,939,728,2045,1101},h)g[404703]=b({e[17034],404703,4,105,252,"「しーっ。今はマジックタイムです、お静かに。一番好きなものを思い浮かべて下さい。…心の声、聞こえましたよ……箱を開けてみて下さい。……中身は僕でした～！　やっぱり、お姉さまが一番好きなのは僕だったんですね！」",200047,2,"deco/character/laien_SD",0,false,1,false,false,false,false,"0",2021,980,398,1128,236,1677,2614,1128,678,1677},h)g[404704]=b({e[21034],404704,3,24,253,"「ハロウィンのりんごは、色鮮やかなものほど毒があるって言われてるんです。お姉さまがくださるものなら、いただきますけど……あぁ、どんな風に起こしてもらえるんでしょう、ドキドキしちゃいます。」",200047,2,"deco/character/laien_WS",0,false,false,false,false,false,false,"0",false,"100,0,1",false,"100,-120,1",1894,891,396,814,699,2545,2369,814,699,2545,1150,1,3769,4173,2104,3618,8000,8500,16000,9667,13000,false,8000},h)g[404801]=b({e[46057],404801,false,120,254,false,200048,false,"deco/character/senchuanlingzi",false,60,1,false,false,false,34,false,false,false,false,false,false,false,false,"120,-70,1.02",false,"-30,50,1",false,false,false,"0,40,1","0,40,1",false,false,false,1844,947,393,953,734,2014,2479,953,734,2014,1170,"senchuanlingzi"},h)g[404802]=b({e[17034],404802,1,4,255,"「こ、これが、君が好きな、お日さまの日差しなの？\nもっと日差しを浴びたら、私も君みたいに、お友達がたくさん出来るかな……。\n頑張ってみるから、明日も、一緒にひなたぼっこしたいの。」",200048,1,"deco/character/senchuanlingzi_0",false,60,1,false,false,false,false,"0",1839,913,399,766,644,2468,2556,766,644,2468,1229,false,false,false,false,false,false,false,false,false,false,false,false,"senchuanlingzi_0"},h)g[404803]=b({e[21034],404803,9,84,256,"「こ、これは……いい夢を見せるための魔法陣なの。お泊りに来てもらった友達は君が初めてだから、その…いい夢を見てもらいたいな……って……」",200048,2,"deco/character/senchuanlingzi_SY",0,false,false,false,false,false,false,false,false,false,false,"0,-140,1",1953,950,380,1005,562,2128,1997,1005,639,2128,false,1,3475,5000,1801,3207,8000,13333,6333,3166,10000,false,8000,"senchuanlingzi_sy"},h)g[404804]=b({e[17034],404804,12,48,257,"「私と一緒に踊りたい、の……？　嬉しいけど、踊るってことは、両手が君の体に触れることになっちゃうの。君に不幸が移るのが怖いの……。君はずっと、この世で一番幸運な人でいて欲しいの。」",200048,2,"deco/character/senchuanlingzi_LF",0,false,1,false,false,false,false,"0",1924,873,388,836,688,2472,2707,836,688,2472,1139,false,false,false,false,false,false,false,false,false,false,false,false,"senchuanlingzi_lf"},h)g[404805]=b({e[24034],404805,3,54,258,"「あの、私の役は『幽霊の花嫁』で……。それで、もし良かったら、台詞の練習に付き合って欲しいの。　じ、じゃあ、始めるの……『ヒ、ヒッヒッヒ、ここまで来たからには、私の魂の、は、半身として残ってもらいます！』」",200048,2,"deco/character/senchuanlingzi_WS",0,false,false,false,false,false,false,false,false,false,"-150,0,1","240,-140,1","-150,0,1","-280,0,1","-150,0,1",2081,842,393,596,473,2868,2869,596,538,2868,false,1,5437,5000,3086,2651,8000,15666,14166,12666,15000,8000,8000,"senchuanlingzi_ws"},h)